<?php
defined( 'ABSPATH' ) || exit;
final class EduFlow_Batch_Service {
	const STATUSES=array('active','paused','closed');
	private static function clean($input,$institute_id){$class=sanitize_key($input['class_type']??'');if(!in_array($class,EduFlow_Admission_Service::CLASS_TYPES,true)){return new WP_Error('invalid_class_type','Invalid class type.');}$teacher=absint($input['teacher_id']??0);if($teacher&&!EduFlow_Teacher_Service::get($teacher,$institute_id)){return new WP_Error('invalid_teacher','Teacher does not belong to this institute.');}$days=EduFlow_Teacher_Service::days($input['days_of_week']??array());if(!$days){return new WP_Error('days_required','Select at least one day.');}$start=sanitize_text_field($input['start_time']??'');$end=sanitize_text_field($input['end_time']??'');if(!$start||!$end||$start>=$end){return new WP_Error('invalid_time','Batch end time must follow start time.');}$start_date=sanitize_text_field($input['start_date']??'');$end_date=sanitize_text_field($input['end_date']??'');if($end_date&&$end_date<$start_date){return new WP_Error('invalid_dates','Batch end date cannot precede start date.');}$timezone=sanitize_text_field($input['timezone']??'');if(!in_array($timezone,timezone_identifiers_list(),true)){$timezone=EduFlow_Settings::get_for_institute($institute_id)['timezone']??'Asia/Kolkata';}return array('batch_name'=>sanitize_text_field($input['batch_name']??''),'course'=>sanitize_text_field($input['course']??''),'level'=>sanitize_text_field($input['level']??''),'class_type'=>$class,'teacher_id'=>$teacher?:null,'capacity'=>max(1,absint($input['capacity']??1)),'days_of_week'=>implode(',',$days),'start_time'=>$start,'end_time'=>$end,'start_date'=>$start_date,'end_date'=>$end_date?:null,'timezone'=>$timezone);}
	public static function create($input,$institute_id=0){global $wpdb;$institute_id=$institute_id?:EduFlow_Settings::institute_db_id();$data=self::clean($input,$institute_id);if(is_wp_error($data)){return $data;}if(!$data['batch_name']||!$data['course']||!$data['start_date']){return new WP_Error('missing_fields','Batch name, course and start date are required.');}$id=EduFlow_ID_Service::generate('batch',$institute_id);if(is_wp_error($id)){return $id;}$now=current_time('mysql',true);$data=array_merge($data,array('canonical_id'=>$id,'institute_id'=>$institute_id,'batch_status'=>'active','status'=>'active','created_at'=>$now,'updated_at'=>$now));if(false===$wpdb->insert(EduFlow_DB::table('batches'),$data)){return new WP_Error('batch_create_failed','Batch could not be created.');}$batch_id=(int)$wpdb->insert_id;self::sync_rule($batch_id,$data);EduFlow_Audit_Service::log('batch_created','batch',$id,null,$data,$institute_id);return $batch_id;}
	public static function get($id,$institute_id=0,$lock=false){global $wpdb;$table=EduFlow_DB::table('batches');$institute_id=$institute_id?:EduFlow_Settings::institute_db_id();return $wpdb->get_row($wpdb->prepare("SELECT * FROM $table WHERE id=%d AND institute_id=%d".($lock?' FOR UPDATE':''),$id,$institute_id),ARRAY_A);}
	public static function update($id,$input,$institute_id=0){global $wpdb;$institute_id=$institute_id?:EduFlow_Settings::institute_db_id();$old=self::get($id,$institute_id);if(!$old){return new WP_Error('not_found','Batch not found.');}$data=self::clean($input,$institute_id);if(is_wp_error($data)){return $data;}$count=self::active_count($id,$institute_id);if($data['capacity']<$count){return new WP_Error('capacity_below_enrollment','Capacity cannot be lower than active enrollment.');}$data['updated_at']=current_time('mysql',true);$wpdb->update(EduFlow_DB::table('batches'),$data,array('id'=>$id,'institute_id'=>$institute_id));self::sync_rule($id,array_merge($old,$data));$schedule_changed=$old['teacher_id']!=$data['teacher_id']||$old['days_of_week']!==$data['days_of_week']||$old['start_time']!==$data['start_time']||$old['end_time']!==$data['end_time']||$old['timezone']!==$data['timezone'];if($schedule_changed){$classes=EduFlow_DB::table('classes');$ids=$wpdb->get_col($wpdb->prepare("SELECT id FROM $classes WHERE institute_id=%d AND batch_id=%d AND class_date>=%s AND class_status IN ('scheduled','rescheduled')",$institute_id,$id,current_time('Y-m-d')));foreach($ids as $class_id){EduFlow_Class_Service::cancel($class_id,$institute_id);$wpdb->query($wpdb->prepare("UPDATE $classes SET schedule_key=CONCAT(schedule_key,':retired:',id) WHERE id=%d AND institute_id=%d",$class_id,$institute_id));}}$action=$old['teacher_id']!=$data['teacher_id']?'teacher_changed':($schedule_changed?'schedule_changed':'batch_updated');EduFlow_Audit_Service::log($action,'batch',$old['canonical_id'],$old,$data,$institute_id);if('teacher_changed'===$action&&$data['teacher_id']){EduFlow_Notification_Service::create('teacher_changed','teacher',$data['teacher_id'],'Batch assigned','A batch has been assigned to you.','teacher-changed:'.$id.':'.$data['teacher_id'].':'.$data['updated_at'],'batch',$id,array('portal','email_ready'),$institute_id);}return true;}
	private static function sync_rule($batch_id,$data){global $wpdb;$table=EduFlow_DB::table('schedule_rules');$now=current_time('mysql',true);$wpdb->query($wpdb->prepare("INSERT INTO $table (institute_id,batch_id,days_of_week,start_time,end_time,timezone,rule_status,status,created_at,updated_at) VALUES (%d,%d,%s,%s,%s,%s,'active','active',%s,%s) ON DUPLICATE KEY UPDATE days_of_week=VALUES(days_of_week),start_time=VALUES(start_time),end_time=VALUES(end_time),timezone=VALUES(timezone),updated_at=VALUES(updated_at)",$data['institute_id'],$batch_id,$data['days_of_week'],$data['start_time'],$data['end_time'],$data['timezone'],$now,$now));}
	public static function set_status($id,$status,$institute_id=0){global $wpdb;$status=sanitize_key($status);if(!in_array($status,self::STATUSES,true)){return new WP_Error('invalid_status','Invalid batch status.');}$institute_id=$institute_id?:EduFlow_Settings::institute_db_id();$old=self::get($id,$institute_id);if(!$old){return new WP_Error('not_found','Batch not found.');}$wpdb->update(EduFlow_DB::table('batches'),array('batch_status'=>$status,'updated_at'=>current_time('mysql',true)),array('id'=>$id,'institute_id'=>$institute_id));$wpdb->update(EduFlow_DB::table('schedule_rules'),array('rule_status'=>'active'===$status?'active':'paused','updated_at'=>current_time('mysql',true)),array('batch_id'=>$id,'institute_id'=>$institute_id));EduFlow_Audit_Service::log('batch_updated','batch',$old['canonical_id'],$old['batch_status'],$status,$institute_id);return true;}
	public static function active_count($batch_id,$institute_id){global $wpdb;$table=EduFlow_DB::table('batch_students');return(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $table WHERE institute_id=%d AND batch_id=%d AND assignment_status='active'",$institute_id,$batch_id));}
	public static function assign_student($batch_id,$student_id,$institute_id=0,$manage_transaction=true){global $wpdb;$institute_id=$institute_id?:EduFlow_Settings::institute_db_id();$table=EduFlow_DB::table('batch_students');if($manage_transaction){$wpdb->query('START TRANSACTION');}$batch=self::get($batch_id,$institute_id,true);$student=EduFlow_Student_Service::get($student_id,$institute_id);if(!$batch||!$student){if($manage_transaction){$wpdb->query('ROLLBACK');}return new WP_Error('invalid_assignment','Batch or student does not belong to this institute.');}if('closed'===$batch['batch_status']){if($manage_transaction){$wpdb->query('ROLLBACK');}return new WP_Error('batch_closed','Cannot assign to a closed batch.');}if(self::active_count($batch_id,$institute_id)>=(int)$batch['capacity']){if($manage_transaction){$wpdb->query('ROLLBACK');}return new WP_Error('batch_full','Batch capacity has been reached.');}$batches=EduFlow_DB::table('batches');$existing=$wpdb->get_results($wpdb->prepare("SELECT b.* FROM $table a INNER JOIN $batches b ON b.id=a.batch_id AND b.institute_id=a.institute_id WHERE a.institute_id=%d AND a.student_id=%d AND a.assignment_status='active' AND b.batch_status<>'closed'",$institute_id,$student_id),ARRAY_A);foreach($existing as $other){$overlap=array_intersect(explode(',',$batch['days_of_week']),explode(',',$other['days_of_week']));$times=$batch['start_time']<$other['end_time']&&$batch['end_time']>$other['start_time'];$dates=(!$batch['end_date']||$batch['end_date']>=$other['start_date'])&&(!$other['end_date']||$other['end_date']>=$batch['start_date']);if($overlap&&$times&&$dates){if($manage_transaction){$wpdb->query('ROLLBACK');}return new WP_Error('student_schedule_conflict','Student has an overlapping batch schedule.');}}$key=$institute_id.':'.$batch_id.':'.$student_id;if(false===$wpdb->insert($table,array('institute_id'=>$institute_id,'batch_id'=>$batch_id,'student_id'=>$student_id,'assignment_key'=>$key,'assignment_status'=>'active','assigned_at'=>current_time('mysql',true),'created_by'=>get_current_user_id(),'status'=>'active','created_at'=>current_time('mysql',true),'updated_at'=>current_time('mysql',true)))){if($manage_transaction){$wpdb->query('ROLLBACK');}return new WP_Error('duplicate_assignment','Student is already assigned to this batch.');}$wpdb->update(EduFlow_DB::table('students'),array('batch_id'=>$batch_id,'updated_at'=>current_time('mysql',true)),array('id'=>$student_id,'institute_id'=>$institute_id));if($manage_transaction){$wpdb->query('COMMIT');}EduFlow_Audit_Service::log('student_assigned','batch_assignment',$wpdb->insert_id,null,array('batch_id'=>$batch_id,'student_id'=>$student_id),$institute_id);EduFlow_Notification_Service::create('student_assigned','student',$student_id,'Batch assigned','You have been assigned to a batch.','batch-assigned:'.$batch_id.':'.$student_id,'batch',$batch_id,array('portal','email_ready','whatsapp_ready'),$institute_id);return true;}
	public static function remove_student($batch_id,$student_id,$institute_id=0,$transfer_to=null){global $wpdb;$institute_id=$institute_id?:EduFlow_Settings::institute_db_id();$table=EduFlow_DB::table('batch_students');$row=$wpdb->get_row($wpdb->prepare("SELECT * FROM $table WHERE institute_id=%d AND batch_id=%d AND student_id=%d AND assignment_status='active'",$institute_id,$batch_id,$student_id),ARRAY_A);if(!$row){return new WP_Error('assignment_not_found','Active assignment not found.');}$wpdb->update($table,array('assignment_key'=>'history:'.$row['id'],'assignment_status'=>$transfer_to?'transferred':'removed','removed_at'=>current_time('mysql',true),'transferred_to_batch_id'=>$transfer_to,'status'=>'history','updated_at'=>current_time('mysql',true)),array('id'=>$row['id'],'institute_id'=>$institute_id));$wpdb->update(EduFlow_DB::table('students'),array('batch_id'=>$transfer_to?:null,'updated_at'=>current_time('mysql',true)),array('id'=>$student_id,'institute_id'=>$institute_id));EduFlow_Audit_Service::log($transfer_to?'student_transferred':'student_removed','batch_assignment',$row['id'],$row,array('transferred_to'=>$transfer_to),$institute_id);return true;}
	public static function transfer_student($from,$to,$student,$institute_id=0){global $wpdb;$institute_id=$institute_id?:EduFlow_Settings::institute_db_id();$wpdb->query('START TRANSACTION');$assigned=self::assign_student($to,$student,$institute_id,false);if(is_wp_error($assigned)){$wpdb->query('ROLLBACK');return $assigned;}$removed=self::remove_student($from,$student,$institute_id,$to);if(is_wp_error($removed)){$wpdb->query('ROLLBACK');return $removed;}$wpdb->query('COMMIT');return true;}
}
